def subtract(a, b):
    # Filter out empty intervals and sort
    a = sorted([interval for interval in a if interval[0] < interval[1]])
    b = sorted([interval for interval in b if interval[0] < interval[1]])

    # Merge overlapping/touching intervals in b
    merged_b = []
    for start, end in b:
        if merged_b and start <= merged_b[-1][1]:
            merged_b[-1][1] = max(merged_b[-1][1], end)
        else:
            merged_b.append([start, end])

    # Compute a - b
    result = []
    for a_start, a_end in a:
        current = a_start
        for b_start, b_end in merged_b:
            if b_end <= current:
                # b interval is entirely before current position
                continue
            if b_start >= a_end:
                # b interval is entirely after remaining a interval
                break
            if b_start > current:
                # There's a gap in b coverage - add it
                result.append([current, b_start])
            current = max(current, b_end)

        if current < a_end:
            # Add remaining part of a interval
            result.append([current, a_end])

    # Merge touching intervals in result
    final = []
    for start, end in result:
        if final and start <= final[-1][1]:
            final[-1][1] = max(final[-1][1], end)
        else:
            final.append([start, end])

    return final

